function makeTournament(names:string[]){const size=names.length,all:Game[]=[];const build=(stage:"main"|"challenge",count:number,prefix:string)=>{const rounds=Math.log2(count),ids:string[][]=[];for(let r=0;r<rounds;r++){const matches=count/(2**(r+1)),label=matches===1?"決勝":matches===2?"準決勝":matches===4?"準々決勝":r===0?"1回戦":`第${r+1}ラウンド`;ids[r]=[];for(let i=0;i<matches;i++){const id=`${prefix}-${r}-${i}`,total=540+all.length*40;ids[r].push(id);all.push({id,no:`${prefix.toUpperCase()}${String(all.length+1).padStart(2,"0")}`,time:`${String(Math.floor(total/60)).padStart(2,"0")}:${String(total%60).padStart(2,"0")}`,court:`${i%2?"B":"A"}コート`,round:label,a:r===0&&stage==="main"?names[i*2]:null,b:r===0&&stage==="main"?names[i*2+1]:null,sa:0,sb:0,done:false,stage,ya:0,yb:0,ra:0,rb:0})}}for(let r=0;r<ids.length-1;r++)ids[r].forEach((id,i)=>{const g=all.find(x=>x.id===id)!;g.nextId=ids[r+1][Math.floor(i/2)];g.nextSlot=i%2?"b":"a"});return ids};const main=build("main",size,"m"),challenge=size>=4?build("challenge",size/2,"c"):[];if(challenge.length)main[0].forEach((id,i)=>{const g=all.find(x=>x.id===id)!;g.loseNextId=challenge[0][Math.floor(i/2)];g.loseNextSlot=i%2?"b":"a"});return all}
function makeLeague(names:string[],cycles=1){const pool=[...names],first:Game[]=[];if(pool.length%2)pool.push("");const rounds=pool.length-1,half=pool.length/2;for(let r=0;r<rounds;r++){for(let i=0;i<half;i++){const a=pool[i],b=pool[pool.length-1-i];if(!a||!b)continue;first.push({id:`l-1-${r}-${i}`,no:"",time:"",court:"Aコート",round:`第${r+1}節`,a:r%2?a:b,b:r%2?b:a,sa:0,sb:0,done:false,stage:"league",ya:0,yb:0,ra:0,rb:0})}pool.splice(1,0,pool.pop()!)}const games=[...first];if(cycles===2)first.forEach((g,i)=>{const round=Number(g.round.replace(/\D/g,""))+rounds;games.push({...g,id:`l-2-${i}`,round:`第${round}節`,a:g.b,b:g.a})});let startSlot=0;Array.from(new Set(games.map(g=>g.round))).forEach(round=>{const roundGames=games.filter(g=>g.round===round);roundGames.forEach((g,i)=>{const slot=startSlot+Math.floor(i/2),total=540+slot*40;g.time=`${String(Math.floor(total/60)).padStart(2,"0")}:${String(total%60).padStart(2,"0")}`;g.court=`${i%2?"B":"A"}コート`});startSlot+=Math.ceil(roundGames.length/2)+1});games.forEach((g,i)=>g.no=`L${String(i+1).padStart(2,"0")}`);return games}
function Mark({name}:{name:string|null}){let i=Math.abs((name||"").split("").reduce((n,c)=>n+c.charCodeAt(0),0))%colors.length;return <i className="mark" style={{background:colors[i]}}>{name?.[0]||"?"}</i>}
function Team({name}:{name:string|null}){return <span className={!name?"team muted":"team"}><Mark name={name}/>{name||"対戦待ち"}</span>}
function Card({g}:{g:Game}){return <div className={g.done?"game done":"game"}><small>{g.no}{g.done&&<em><Check/>終了</em>}</small><p><Team name={g.a}/><b>{g.done?g.sa:"–"}</b></p><p><Team name={g.b}/><b>{g.done?g.sb:"–"}</b></p>{g.pa!==undefined&&<footer>PK {g.pa} - {g.pb}</footer>}</div>}

