 useEffect(()=>{if(!running)return;let t=setInterval(()=>setSecsRaw(s=>s+1),1000);return()=>clearInterval(t)},[running]);useEffect(()=>{if(!paused)return;let t=setInterval(()=>activeHalf==="前半"?setLossFirst(s=>s+1):setLossSecond(s=>s+1),1000);return()=>clearInterval(t)},[paused,activeHalf]);useEffect(()=>{if(!undoToast)return;let t=setTimeout(()=>setUndoToast(false),3000);return()=>clearTimeout(t)},[undoToast,undoStack]); useEffect(()=>setSecsRaw(0),[mins]);useEffect(()=>{try{let saved=localStorage.getItem("fieldsync_pending_result");if(saved)setPendingResult(JSON.parse(saved))}catch{}},[]);
 const win=(x:Game)=>{if(x.sa!==x.sb)return x.sa>x.sb?x.a:x.b;if(x.pka||x.pkb){const a=x.pka||[],b=x.pkb||[],pa=a.filter(v=>v==="o").length,pb=b.filter(v=>v==="o").length;if(a.length<pkRule||b.length<pkRule){if(pa>pb+Math.max(0,pkRule-b.length))return x.a;if(pb>pa+Math.max(0,pkRule-a.length))return x.b;return null}return a.length===b.length&&pa!==pb?(pa>pb?x.a:x.b):null}return(x.pa||0)!==(x.pb||0)?((x.pa||0)>(x.pb||0)?x.a:x.b):null}; const lose=(x:Game)=>win(x)===x.a?x.b:win(x)===x.b?x.a:null;
 const nav=(t:Tab)=>{if(t==="score"&&!staff)setLogin(true);else if((t==="settings"||t==="system")&&!admin)setLogin(true);else setTab(t)};
