 const commitResult=(result:Game)=>{let w=win(result),l=lose(result);if(!w&&result.stage!=="league")return;setGames(xs=>xs.map(x=>{if(x.id===result.id)return{...result,done:true};if(result.nextId===x.id&&result.nextSlot)return{...x,[result.nextSlot]:w};if(result.loseNextId===x.id&&result.loseNextSlot)return{...x,[result.loseNextSlot]:l};if(result.id==="m3"&&x.id==="m6")return{...x,a:w};if(result.id==="m4"&&x.id==="m6")return{...x,b:w};if(result.id==="m3"&&x.id==="c2")return{...x,a:l};if(result.id==="m4"&&x.id==="c2")return{...x,b:l};if(result.id==="m5"&&x.id==="m7")return{...x,a:w};if(result.id==="m6"&&x.id==="m7")return{...x,b:w};if(result.id==="c1"&&x.id==="c3")return{...x,a:w};if(result.id==="c2"&&x.id==="c3")return{...x,b:w};return x}));setPhase("試合終了");setRunning(false);setUndoStack([]);setUndoToast(false)};
